// features/lifecycle.feature: A page past the last vendor is empty but still reports the total
import { expect, expectStatus, test, uniqueName } from "../../fixtures";

test("a page past the last vendor is empty but still reports the total", { tag: "@LIF-15" }, async ({ apiAs, factory }) => {
  // Arrange: vendors sharing a unique prefix, so parallel tests can't change this total
  const prefix = uniqueName("Paging");
  await factory.vendor({ name: `${prefix} one` });
  await factory.vendor({ name: `${prefix} two` });
  await factory.vendor({ name: `${prefix} three` });
  const member = await apiAs("member");
  const firstPage = await expectStatus<{ items: unknown[]; total: number }>(
    await member.get("/api/vendors", { params: { q: prefix, limit: 20, offset: 0 } }),
    200,
  );
  expect(firstPage.total).toBe(3);

  // Act
  const beyond = firstPage.total + 10;
  const response = await member.get("/api/vendors", { params: { q: prefix, limit: 20, offset: beyond } });

  // Assert
  const page = await expectStatus<{ items: unknown[]; total: number; offset: number }>(response, 200);
  expect(page.items).toEqual([]);
  expect(page.total).toBe(firstPage.total);
  expect(page.offset).toBe(beyond);
});
